  const deleteTask = (id) => setTasks(tasks.filter(t => t.id !== id));

  return (
    <div className="app-container">
      <h1>To-Do List</h1>
      <form onSubmit={addTask}>
        <input value={text} onChange={(e) => setText(e.target.value)} />
