    setTimeout(() => {
      if (Math.random() > 0.8) dispatch({ type: "SYNC", payload: previousState }); 
    }, 1000);
  }, [dispatch, state.version, state]);

  return (
    <div className={`board-container ${theme === 'dark' ? 'dark-mode' : ''}`}>
      <h1>Kanban Board</h1>
      <div className="board">
        {state.columns.map(col => (
